<script setup lang="ts">
import { computed, ref } from 'vue'
import { activeTasks, api, refresh, state } from '../api'
import { labels, terminal } from '../types'
import type { Task } from '../types'
const busy = ref(false), error = ref('')
function taskTitle(task:Task) { return state.sources.find(s=>s.id===task.source_id)?.title || state.editions.find(e=>e.id===task.parameters.edition_id)?.name || task.parameters.name || task.parameters.url || '' }
const networkTask=(task:Task) => ['download','resume','refresh'].includes(task.kind)
const finished = computed(() => state.tasks.filter(terminal))
async function stop() { if (busy.value) return; busy.value=true; error.value=''; try { await api('/tasks/stop-all', { method:'POST' }); await refresh() } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
function date(value: number) { return new Date(value*1000).toLocaleString('zh-CN', { month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit' }) }
</script>
<template>
  <div class="page-heading"><div><h1>任务中心</h1></div><button class="button danger" :disabled="busy || !activeTasks.length || state.info?.stopping" @click="stop">{{ state.info?.stopping ? '正在停止…' : '停止全部' }}</button></div>
  <p class="hint stop-note">停止会立即中断网络请求并取消排队任务，不再自动导出。已提交的正文保留，可稍后手动导出。</p><p v-if="error" class="message error" role="alert">{{ error }}</p>
  <section class="panel"><div class="panel-heading"><div><h2>当前任务 <span class="count">{{ activeTasks.length }}</span></h2><p>同时运行一个任务，章节按本次设置并发处理。</p></div><span class="subtle-label">自动更新</span></div><div v-if="!activeTasks.length" class="empty"><div class="empty-symbol">◷</div><h3>暂时没有进行中的任务</h3><RouterLink to="/" class="button">前往书库 →</RouterLink></div>
  <article v-for="task in activeTasks" :key="task.id" class="task-card"><div class="task-top"><div><h3>{{ labels[task.kind] }} <span class="muted">{{ taskTitle(task) }}</span></h3><small>{{ date(task.created_at) }} · {{ task.id.slice(0,8) }}</small></div><span :class="['badge', task.status]">{{ labels[task.status] }}</span></div><template v-if="task.status !== 'queued'"><div class="progress-label"><span>{{ labels[task.phase] || task.phase }}</span><b v-if="networkTask(task)">{{ task.processed }} / {{ task.total }} 章</b></div><progress v-if="networkTask(task)" :value="task.processed" :max="task.total || 1"></progress><div v-if="networkTask(task)" class="task-details"><span>本次成功 <b>{{ task.succeeded }}</b></span><span>本次失败 <b>{{ task.failed }}</b></span><span v-if="task.current_chapters?.length">目录位置 {{ task.current_chapters.join('、') }} · 第 {{ task.attempt }} 次尝试</span><span v-if="task.parameters.start_position">从位置 {{ task.parameters.start_position }} 开始</span><span v-if="task.wait_until">等待至 {{ new Date(task.wait_until*1000).toLocaleTimeString() }}</span></div><p v-if="task.source_progress" class="hint">范围内保存状态：{{ task.source_progress.completed }} 已保存 / {{ task.source_progress.total }} 章（与本次处理进度分别统计）</p></template></article></section>
  <section class="panel history"><div class="panel-heading"><div><h2>本次运行记录</h2><p>最近 100 项，退出服务后清空；章节和正文不会清除。</p></div></div><div v-if="!finished.length" class="empty compact">完成的任务将显示在这里。</div><article v-for="task in finished" :key="task.id" class="task-card"><div class="task-top"><div><h3>{{ labels[task.kind] }} <span class="muted">{{ taskTitle(task) }}</span></h3><small>{{ date(task.created_at) }}<template v-if="networkTask(task)"> · 成功 {{ task.succeeded }} / 失败 {{ task.failed }}</template></small></div><span :class="['badge', task.status]">{{ labels[task.status] }}</span></div><RouterLink v-if="task.source_id" :to="`/sources/${task.source_id}`" class="text-button task-source">查看来源与章节 →</RouterLink><p v-if="task.error" class="message error">{{ task.error }}</p><p v-if="task.result?.path" class="hint file-path">{{ task.result.path }}</p><a v-if="task.result?.download_url" :href="task.result.download_url" class="text-button" download>下载 TXT ↓</a><RouterLink v-if="task.result?.edition_id" :to="`/editions/${task.result.edition_id}`" class="text-button">查看合并版本 →</RouterLink></article></section>
</template>
